sp_search_source.data_fetch_script:
(function(query) {
    var results = [];

    // zober query bezpečne
    var q = '';
    if (typeof query !== 'undefined' && query) {
        q = (query + '').trim();
    }

    // pomocná funkcia
    function addPeopleResults(tableName, roleName, detailPage) {
        var gr = new GlideRecord(tableName);

        if (q) {
            gr.addEncodedQuery('nameCONTAINS' + q + '^ORbiographyCONTAINS' + q);
        }

        gr.orderBy('name');
        gr.setLimit(10);
        gr.query();

        while (gr.next()) {
            results.push({
                table: tableName,
                sys_id: gr.getValue('sys_id'),
                title: gr.getValue('name'),
                description: gr.getValue('biography'),
                profile_url: gr.getValue('profile_url'),
                role: roleName,
                url: '/mep?id=' + detailPage + '&sys_id=' + gr.getValue('sys_id')
            });
        }
    }

    // actors
    addPeopleResults('x_1080820_mvx_actor', 'Actor', 'actor_detail');

    // directors
    addPeopleResults('x_1080820_mvx_director', 'Director', 'director_detail');

    return results;
})(query);

